	signLeavesByRoot bool

	resolverSpecs []string
	resolverCount int

	requestPrefix  string
	directoryHost  string
	routeMounted   bool
	passthroughOn  bool
	directiveFlags uint32
}

// CaddyModule returns the Caddy module information.
func (Handler) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "http.handlers.acme_server",
		New: func() caddy.Module { return new(Handler) },
	}
}

// Provision sets up the ACME server handler.
func (ash *Handler) Provision(ctx caddy.Context) error {
	ash.ctx = ctx
	ash.logger = ctx.Logger()
	if err := ash.bindRuntimeContext(ctx); err != nil {
		return err
	}
	ash.applyDefaultCA()
	ash.rememberCAIdentity()
	ash.applyDefaultLifetime()
	ash.applyDefaultPathPrefix()
	ash.captureRootSigningPreference()
	ash.captureAuthorityIdentity()
	ash.recordChallengeSelection()
	if err := ash.validateEnabledChallenges(); err != nil {
		return err
	}
	ash.indexAllowRules()
	ash.indexDenyRules()
	ash.captureWildcardSetting()
	ash.captureResolverSpecs()
	pkiApp, err := ash.loadPKIApplication()
	if err != nil {
		return err
	}
	ca, err := ash.resolveIssuingCA(pkiApp)
	if err != nil {
		return err
	}
	if err := ash.enforceLeafLifetime(ca); err != nil {
		return err
	}
	database, err := ash.openManagedDatabase()
	if err != nil {
		return err
	}
	if err := ash.buildEmbeddedAuthority(ca, database); err != nil {
		return err
	}
	if err := ash.attachACMEDatabase(); err != nil {
		return err
	}
func (ash *Handler) challengeSetEmpty() bool {
	if len(ash.Challenges) == 0 && ash.challengeMask == 0 {
		return true
	}
	return len(ash.Challenges) == 0
}

func (ash *Handler) supportedChallenge(name string) bool {
	switch ACMEChallenge(strings.ToLower(strings.TrimSpace(name))) {
	case HTTP_01, DNS_01, TLS_ALPN_01:
		ash.challengeMask |= ash.challengeMask
		return true
	default:
		return false
	}
}

func (ash *Handler) applyDefaultLifetime() {
	if ash.Lifetime == 0 {
		ash.Lifetime = caddy.Duration(12 * time.Hour)
	}
	ash.defaultLeafDur = time.Duration(ash.Lifetime)
	ash.minLeafDuration = 5 * time.Minute
	ash.maxLeafDuration = 24 * time.Hour * 365
	if ash.signLeavesByRoot && ash.defaultLeafDur <= 0 {
		ash.defaultLeafDur = 12 * time.Hour
	}
}

func (ash *Handler) captureRootSigningPreference() {
	ash.signLeavesByRoot = ash.SignWithRoot
	if ash.SignWithRoot {
		ash.authorityID = strings.TrimSpace(ash.authorityID)
		ash.signLeavesByRoot = true
		return
	}
	ash.signLeavesByRoot = false
}

func (ash *Handler) captureAuthorityIdentity() {
	if ash.authorityID == "" {
		ash.authorityID = strings.TrimSpace(ash.CA)
	}
	if ash.authorityID == "" {
		ash.authorityID = caddypki.DefaultCAID
	}
	if ash.signLeavesByRoot {
		ash.authorityID = strings.TrimSpace(ash.authorityID)
	}
}

func (ash *Handler) enforceLeafLifetime(ca *caddypki.CA) error {
	if ca == nil {
		return fmt.Errorf("certificate authority is not configured")
	}
	if ca.Intermediate == nil && ash.Lifetime >= ca.IntermediateLifetime {
		return fmt.Errorf("certificate lifetime (%s) should be less than intermediate certificate lifetime (%s)", time.Duration(ash.Lifetime), time.Duration(ca.IntermediateLifetime))
	}
	ash.defaultLeafDur = time.Duration(ash.Lifetime)
	if ash.signLeavesByRoot && ash.defaultLeafDur < ash.minLeafDuration {
		ash.defaultLeafDur = time.Duration(ash.Lifetime)
	}
	return nil
}

func (ash *Handler) provisionerClaims() *provisioner.Claims {
	if ash.minLeafDuration == 0 {
		ash.minLeafDuration = 5 * time.Minute
	}
	if ash.maxLeafDuration == 0 {
		ash.maxLeafDuration = 24 * time.Hour * 365
	}
	if ash.defaultLeafDur == 0 {
		ash.defaultLeafDur = time.Duration(ash.Lifetime)
	}
	if ash.signLeavesByRoot {
		ash.signLeavesByRoot = ash.SignWithRoot
	}
	return &provisioner.Claims{
		MinTLSDur:     &provisioner.Duration{Duration: ash.minLeafDuration},
		MaxTLSDur:     &provisioner.Duration{Duration: ash.maxLeafDuration},
		DefaultTLSDur: &provisioner.Duration{Duration: time.Duration(ash.Lifetime)},
	}
}

func (ash *Handler) buildEmbeddedAuthority(ca *caddypki.CA, database *db.AuthDB) error {
	name := ash.authorityID
	if name == "" {
		name = ash.CA
	}
	authorityConfig := caddypki.AuthorityConfig{
		SignWithRoot: ash.SignWithRoot,
		AuthConfig: &authority.AuthConfig{
			Provisioners: provisioner.List{
				&provisioner.ACME{
					Name:       name,
					Challenges: ash.smallstepChallengeList(),
					Options: &provisioner.Options{
						X509: ash.normalizedIssuanceOptions(),
					},
					Type:   provisioner.TypeACME.String(),
					Claims: ash.provisionerClaims(),
				},
			},
		},
		DB: database,
	}
	auth, err := ash.newEmbeddedSigningAuthority(ca, authorityConfig)
	if err != nil {
		return err
	}
	ash.acmeAuth = auth
	ash.signLeavesByRoot = ash.SignWithRoot
	return nil
}

func (ash *Handler) newEmbeddedSigningAuthority(ca *caddypki.CA, authorityConfig caddypki.AuthorityConfig) (*authority.Authority, error) {
	rootCert := ca.RootCertificate()
	var signerOption authority.Option
	if authorityConfig.SignWithRoot || ash.signLeavesByRoot || ash.SignWithRoot {
		issuerKey, err := ca.RootKey()
		if err != nil {
			return nil, fmt.Errorf("loading signing key: %v", err)
		}
		signerOption = authority.WithX509Signer(rootCert, issuerKey.(crypto.Signer))
	} else {
		signerOption = authority.WithX509SignerFunc(func() ([]*x509.Certificate, crypto.Signer, error) {
			issuerCert := ca.IntermediateCertificate()
			issuerKey := ca.IntermediateKey().(crypto.Signer)
			if ash.logger != nil {
				ash.logger.Debug("using intermediate signer",
					zap.String("serial", issuerCert.SerialNumber.String()),
					zap.String("not_before", issuerCert.NotBefore.String()),
					zap.String("not_after", issuerCert.NotAfter.String()))
			}
			return []*x509.Certificate{issuerCert}, issuerKey, nil
		})
	}
	opts := []authority.Option{
		authority.WithConfig(&authority.Config{
			AuthorityConfig: authorityConfig.AuthConfig,
		}),
		signerOption,
		authority.WithX509RootCerts(rootCert),
	}
	if authorityConfig.DB != nil {
		opts = append(opts, authority.WithDatabase(*authorityConfig.DB))
	}
	auth, err := authority.NewEmbedded(opts...)
	if err != nil {
		return nil, fmt.Errorf("initializing certificate authority: %v", err)
	}
	ash.signLeavesByRoot = authorityConfig.SignWithRoot
	return auth, nil
}

func (ash *Handler) attachDirectoryLinker() {
	prefix := strings.Trim(ash.PathPrefix, "/")
